#include <bits/stdc++.h>
#include <omp.h>
using namespace std;
struct Perm{array<unsigned char,5>p,inv;};
struct Base{int n;vector<vector<int>>a;vector<pair<int,int>>E;vector<int>eid;};
Base rd(string path){ifstream in(path);vector<vector<int>>m;string l;while(getline(in,l)){if(l.empty())continue;stringstream ss(l);vector<int>r;int x;while(ss>>x)r.push_back(x);if(!r.empty())m.push_back(r);}int n=m.size();Base b{n,vector<vector<int>>(n),{},vector<int>(n*n,-1)};for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(m[i][j]){int e=b.E.size();b.E.push_back({i,j});b.eid[i*n+j]=b.eid[j*n+i]=e;b.a[i].push_back(j);b.a[j].push_back(i);}return b;}
vector<vector<int>>cycles(const Base&b,int L){vector<vector<int>>o;for(int s=0;s<b.n;s++){vector<int>p{s};uint64_t seen=1ULL<<s;function<void(int)>dfs=[&](int u){if((int)p.size()==L){if(find(b.a[u].begin(),b.a[u].end(),s)!=b.a[u].end()&&p[1]<p.back())o.push_back(p);return;}for(int v:b.a[u])if(v>s&&!(seen>>v&1ULL)){seen|=1ULL<<v;p.push_back(v);dfs(v);p.pop_back();seen&=~(1ULL<<v);}};for(int v:b.a[s])if(v>s){seen|=1ULL<<v;p.push_back(v);dfs(v);p.pop_back();seen&=~(1ULL<<v);}}return o;}
bool is5(const array<unsigned char,5>&p){int x=0;for(int k=1;k<=5;k++){x=p[x];if(x==0)return k==5;}return false;}
struct C{vector<int>w,vars;int type=0,sh=0;};
int main(int ac,char**av){if(ac<4){cerr<<"base cuts assignment\n";return 2;}Base b=rd(av[1]);vector<Perm>G;array<unsigned char,5>a={0,1,2,3,4};do{int iv=0;for(int i=0;i<5;i++)for(int j=i+1;j<5;j++)iv+=a[i]>a[j];if(!(iv&1)){Perm q;q.p=a;for(int i=0;i<5;i++)q.inv[q.p[i]]=i;G.push_back(q);}}while(next_permutation(a.begin(),a.end()));
vector<int>pa(b.n,-1),pe(b.n,-1);queue<int>q;pa[0]=0;q.push(0);while(!q.empty()){int u=q.front();q.pop();for(int v:b.a[u])if(pa[v]<0){pa[v]=u;pe[v]=b.eid[u*b.n+v];q.push(v);}}
vector<int>vo(b.E.size(),-1),cot;for(int e=0;e<(int)b.E.size();e++){bool tr=0;for(int v=1;v<b.n;v++)if(pe[v]==e)tr=1;if(!tr){vo[e]=cot.size();cot.push_back(e);}}int r=cot.size();
auto word=[&](const vector<int>&p){vector<int>w;for(int i=0;i<(int)p.size();i++){int u=p[i],v=p[(i+1)%p.size()],z=vo[b.eid[u*b.n+v]];if(z>=0)w.push_back((u<v?1:-1)*(z+1));}return w;};
vector<C>CS;for(auto&p:cycles(b,16)){C c;c.w=word(p);for(int z:c.w)c.vars.push_back(abs(z)-1);sort(c.vars.begin(),c.vars.end());c.vars.erase(unique(c.vars.begin(),c.vars.end()),c.vars.end());CS.push_back(c);}string line;ifstream cf(av[2]);while(getline(cf,line)){if(line.empty())continue;stringstream ss(line);C c;c.type=1;ss>>c.sh;int z;while(ss>>z)c.w.push_back(z);for(int t:c.w)c.vars.push_back(abs(t)-1);sort(c.vars.begin(),c.vars.end());c.vars.erase(unique(c.vars.begin(),c.vars.end()),c.vars.end());CS.push_back(c);}
auto good=[&](const C&c,const vector<int>&x){array<unsigned char,5>cur={0,1,2,3,4},nxt;for(int zz:c.w){int z=abs(zz)-1;auto&p=zz>0?G[x[z]].p:G[x[z]].inv;for(int s=0;s<5;s++)nxt[s]=p[cur[s]];cur=nxt;}return c.type?cur[c.sh]!=c.sh:is5(cur);};
vector<int>x0(r,-1);ifstream ai(av[3]);while(getline(ai,line)){if(line.empty()||line.rfind("FOUND",0)==0)continue;stringstream ss(line);int u,v;ss>>u>>v;array<unsigned char,5>p;for(int k=0;k<5;k++){int z;ss>>z;p[k]=z;}int var=vo[b.eid[u*b.n+v]];if(var>=0)for(int g=0;g<(int)G.size();g++)if(G[g].p==p)x0[var]=g;}
vector<char>ok(CS.size());vector<int>badc,focus;for(int i=0;i<(int)CS.size();i++){ok[i]=good(CS[i],x0);if(!ok[i]){badc.push_back(i);focus.insert(focus.end(),CS[i].vars.begin(),CS[i].vars.end());}}sort(focus.begin(),focus.end());focus.erase(unique(focus.begin(),focus.end()),focus.end());cerr<<"constraints="<<CS.size()<<" initial_bad="<<badc.size()<<" focus";for(int v:focus)cerr<<" "<<v;cerr<<"\n";if(badc.empty()){cerr<<"already solved\n";return 0;}
vector<array<int,3>> triples;for(int v1:focus)for(int v2=0;v2<r;v2++)if(v2!=v1)for(int v3=v2+1;v3<r;v3++)if(v3!=v1){array<int,3>t={v1,v2,v3};sort(t.begin(),t.end());if(find(triples.begin(),triples.end(),t)==triples.end())triples.push_back(t);}cerr<<"triples="<<triples.size()<<"\n";
atomic<bool>found(false);vector<int>sol;omp_set_num_threads(min(16,omp_get_max_threads()));
#pragma omp parallel for schedule(dynamic,1)
for(int ti=0;ti<(int)triples.size();ti++){if(found.load())continue;auto T=triples[ti];vector<int>aff;for(int ci=0;ci<(int)CS.size();ci++){for(int v:CS[ci].vars)if(v==T[0]||v==T[1]||v==T[2]){aff.push_back(ci);break;}}vector<int>x=x0;for(int z0=0;z0<60&&!found.load();z0++){x[T[0]]=z0;for(int z1=0;z1<60&&!found.load();z1++){x[T[1]]=z1;for(int z2=0;z2<60;z2++){x[T[2]]=z2;bool all=1;for(int ci:aff)if(!good(CS[ci],x)){all=0;break;}if(all){bool expected=false;if(found.compare_exchange_strong(expected,true)){sol=x; cerr<<"FOUND triple "<<T[0]<<" "<<T[1]<<" "<<T[2]<<" vals "<<z0<<" "<<z1<<" "<<z2<<"\n";}break;}}}}
}
if(!found){cout<<"NONE_K3\n";return 1;}cout<<"FOUND\n";for(int i=0;i<r;i++){auto[u,v]=b.E[cot[i]];cout<<u<<" "<<v;for(int s=0;s<5;s++)cout<<" "<<(int)G[sol[i]].p[s];cout<<"\n";}return 0;}
